from typing import Dict, Any


def create_translation_request(text: str, source_lang: str, target_lang: str) -> Dict[str, Any]:
    return {
        'text': text,
        'source_lang': source_lang,
        'target_lang': target_lang
    }


def parse_translation_response(response: Dict[str, Any]) -> str:
    return response.get('translated_text', '')


def normalize_text(text: str) -> str:
    return text.strip().lower()

from google.cloud import translate_v2 as translate

def translate_dictionary_values(dictionary, target_language):
    client = translate.Client()
    translated_dict = {}
    for key, value in dictionary.items():
        result = client.translate(value, target_language=target_language)
        translated_dict[key] = result['translatedText']
    return translated_dict

import boto3

def translate_markup(markup, source_lang, target_lang):
    client = boto3.client('translate')
    translated_text = ''
    current_tag = ''
    in_tag = False

    for char in markup:
        if char == '<':
            in_tag = True
            current_tag += char
        elif char == '>':
            in_tag = False
            current_tag += char
            translated_text += current_tag
            current_tag = ''
        elif in_tag:
            current_tag += char
        else:
            if not current_tag:
                response = client.translate_text(Text=char, SourceLanguageCode=source_lang, TargetLanguageCode=target_lang)
                translated_text += response['TranslatedText']
            else:
                current_tag += char
    return translated_text

